create table social_publications(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants,title text not null,content text not null default '',media jsonb not null default '[]',channel_ids int[] not null default '{}',time_zone text not null default 'America/Sao_Paulo',schedule_at timestamptz,status text not null default 'draft',remote_id text,request_key uuid not null unique,results jsonb not null default '[]',error text,version int not null default 1,created_by int references users,created_at timestamptz not null default now(),submitted_at timestamptz,checked_at timestamptz);
alter table social_publications enable row level security;alter table social_publications force row level security;create policy tenant_iso on social_publications using(tenant_id=nullif(current_setting('app.tenant',true),'')::int) with check(tenant_id=nullif(current_setting('app.tenant',true),'')::int);
create trigger fk_guard before insert or update on social_publications for each row execute function fk_guard('users','created_by');
create index social_schedule on social_publications(tenant_id,schedule_at);
